final class FixtureRunnerTest {
    @Test
    void readsEveryPinnedPiDomainIndependently() throws Exception {
        Path root = Path.of("../../../contracts/fixtures");
        var manifest = new ObjectMapper().readTree(root.resolve("manifest.json").toFile());
        assertEquals(5, manifest.path("fixtures").size());
        for (var fixture : manifest.path("fixtures")) {
            var normalized = FixtureRunner.normalize(root.resolve(fixture.path("path").asText()));
            assertEquals("ji-pi-projection-v1", normalized.path("schemaVersion").asText());
            assertEquals(fixture.path("domain").asText(), normalized.path("domain").asText());
            assertEquals(
                    new ObjectMapper().readTree(root.resolve(fixture.path("expectedPath").asText()).toFile()),
                    normalized);
        }
    }

